   231→    commitmentBytes.push(...kzgCommitments);
   232→    cellIndices.push(...Array.from({length: column.length}, () => columnIndex));
   233→    cells.push(...column);
   234→    proofBytes.push(...kzgProofs);
   235→  }
   236→
   237→  if (opts.skipProofsCheck) {
   238→    return;
   239→  }
   240→
   241→  let valid: boolean;
   242→  try {
   243→    const timer = metrics?.peerDas.kzgVerificationDataColumnBatchTime.startTimer();
