   245→    timer?.();
   246→  } catch (err) {
   247→    (err as Error).message =
   248→      `Error in verifyCellKzgProofBatch for slot=${blockSlot} blockRoot=${toRootHex(blockRoot)} commitmentBytes=${commitmentBytes.length} cellIndices=${cellIndices.length} cells=${cells.length} proofBytes=${proofBytes.length}`;
   249→    throw err;
   250→  }
   251→
   252→  if (!valid) {
   253→    throw new Error(`Invalid data column sidecars in slot=${blockSlot} blockRoot=${toRootHex(blockRoot)}`);
   254→  }
   255→}
   256→
   257→/**
   258→ * SPEC FUNCTION
   259→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#verify_data_column_sidecar
   260→ */
   261→export function verifyDataColumnSidecar(dataColumnSidecar: fulu.DataColumnSidecar): void {
   262→  if (dataColumnSidecar.index >= NUMBER_OF_COLUMNS) {
   263→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   264→      code: DataColumnSidecarErrorCode.INVALID_INDEX,
   265→      columnIdx: dataColumnSidecar.index,
   266→    });
   267→  }
   268→
   269→  if (dataColumnSidecar.kzgCommitments.length === 0) {
   270→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   271→      code: DataColumnSidecarErrorCode.NO_COMMITMENTS,
   272→      columnIdx: dataColumnSidecar.index,
   273→    });
   274→  }
   275→
   276→  if (
   277→    dataColumnSidecar.column.length !== dataColumnSidecar.kzgCommitments.length ||
   278→    dataColumnSidecar.column.length !== dataColumnSidecar.kzgProofs.length
   279→  ) {
   280→    throw new DataColumnSidecarGossipError(GossipAction.REJECT, {
   281→      code: DataColumnSidecarErrorCode.MISMATCHED_LENGTHS,
   282→      columnLength: dataColumnSidecar.column.length,
   283→      commitmentsLength: dataColumnSidecar.kzgCommitments.length,
   284→      proofsLength: dataColumnSidecar.kzgProofs.length,
   285→    });
   286→  }
   287→}
   288→
   289→/**
   290→ * SPEC FUNCTION
   291→ * https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.4/specs/fulu/p2p-interface.md#verify_data_column_sidecar_kzg_proofs
   292→ */
